enum Token { case op(String), num(Int), lparen, rparen }
struct Rule { let lbp: Int; let led: (inout Parser, Expr) throws -> Expr }

mutating func parseExpr(minBp: Int) throws -> Expr {
    var left = try parsePrefix()                       // null denotation
    while minBp < rule(for: peek()).lbp {              // left denotation
        let op = consume()
        left = try rule(for: op).led(&self, left)
    }
    return left
}
